    /* cos v = D/N, sin v = 2XY/N (D, 2XY with integral limbs di, si) */
    flint_mpn_mulhigh_n(ycos, X2, I, 4);
    flint_mpn_mulhigh_n(ysin, XY, I, 4);
    mx = -di;
    XF[0] = I[0] & mx;
    XF[1] = I[1] & mx;
    XF[2] = I[2] & mx;
    XF[3] = I[3] & mx;
